// #7e3811 (c99eb276d2d9317f787e3811) «מסך הדוח ב-390: הודעת השגיאה ו«פנייה לתמיכה» מתחילות 1593 פיקסלים מתחת לראש הדף».
// Решение на сайте — вариант AC «נגיש מראש הדף»: ссылка «מעבר לדוח» (data-testid skip-to-report) в первом экране,
// переход ставит фокус на колонку отчёта #report-column. Кейсы RPT390-001…003.
// Окно — десктопный Chromium 390×844 БЕЗ эмуляции телефона (экран бизнеса — только десктоп, урок L-20261014-5).
// Данные: готовый отчёт QA-4b397a-DISC-2110 (business testim). Состояние «שגיאה בהפקת דוח» на сайте не воспроизводится →
// подмена: настоящий ответ get_candidate_report с report.status = generation_error (route.fetch + fulfill).
// Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { openWithApi } from '../support/api';
import { listCandidates } from '../candidates/hiring-support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#7e3811 · #c99eb276d2d9317f787e3811';
const CANDIDATE = process.env.QA_REPORT_390_CANDIDATE || 'QA-4b397a-DISC-2110';
const NARROW = { width: 390, height: 844 };

async function candidateIdByName(page: Page, name: string): Promise<string> {
  const api = await openWithApi(page, '/candidates');
  const found = (await listCandidates(api)).filter((c) => c.full_name === name);
  expect(found, `кандидат «${name}» не найден в list_candidates (QA-данные 21.10.2026)`).toHaveLength(1);
  return found[0].id;
}

/** Настоящий ответ get_candidate_report, но отчёт в статусе generation_error. */
async function forceGenerationError(page: Page) {
  await page.route('**/rest/v1/rpc/get_candidate_report', async (route) => {
    const res = await route.fetch();
    const body = await res.json();
    const row = Array.isArray(body) ? body[0] : body;
    if (row?.report) row.report.status = 'generation_error';
    await route.fulfill({ response: res, json: body });
  });
}

/** Верх/низ элемента относительно окна при текущей прокрутке. */
const rect = (page: Page, testId: string) =>
  page.getByTestId(testId).first().evaluate((e) => {
    const r = e.getBoundingClientRect();
    return { top: r.top, bottom: r.bottom, scrollY: window.scrollY, vh: window.innerHeight };
  });

const reportColumnFocused = (page: Page) => page.evaluate(() => document.activeElement?.id === 'report-column');

test.describe(`Отчёт на ширине 390 — доступ к отчёту с верха страницы (${HASH})`, () => {
  test(`390×844, готовый отчёт: «מעבר לדוח» в первом экране; клик и Enter переводят фокус на колонку отчёта, отчёт виден в окне @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await page.setViewportSize(NARROW);
    const id = await candidateIdByName(page, CANDIDATE);
    await page.goto(`/candidates/${id}/report`);
    await expect(page.getByTestId('report-summary')).toBeAttached({ timeout: 30_000 });

    // Источник: AC1 «תוכן הדוח … נגיש מראש הדף בלי לגלול את כל העמודה הצדדית».
    const skip = page.getByTestId('skip-to-report');
    await expect(skip).toBeVisible();
    await expect(skip).toHaveText('מעבר לדוח');
    await expect(skip).toHaveAttribute('href', '#report-column');
    const s = await rect(page, 'skip-to-report');
    expect(s.scrollY, 'страница должна быть в начале').toBe(0);
    expect(s.bottom, 'ссылка «מעבר לדוח» не в первом экране 844').toBeLessThanOrEqual(NARROW.height);

    // Клик мышью.
    await skip.click();
    await expect.poll(() => reportColumnFocused(page), { message: 'фокус не на #report-column после клика' }).toBe(true);
    await expect(page.locator('#report-column')).toBeInViewport();
    await expect(page.getByTestId('report-summary')).toBeInViewport();

    // Клавиатура: фокус на ссылке, Enter.
    await page.evaluate(() => window.scrollTo(0, 0));
    await skip.focus();
    await expect(skip).toBeFocused();
    await page.keyboard.press('Enter');
    await expect.poll(() => reportColumnFocused(page), { message: 'фокус не на #report-column после Enter' }).toBe(true);
    await expect(page.locator('#report-column')).toBeInViewport();
  });

  test(`390×844, «שגיאה בהפקת דוח» (подмена ответа): «מעבר לדוח» в первом экране; после перехода в окне блок ошибки и «פנייה לתמיכה» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await page.setViewportSize(NARROW);
    const id = await candidateIdByName(page, CANDIDATE);
    await forceGenerationError(page);
    await page.goto(`/candidates/${id}/report`);

    // Источник: AC2 «כשהפקת הדוח נכשלה, הודעת השגיאה והכפתור «פנייה לתמיכה» … נגישים מראש הדף»; было 1593 px.
    const error = page.getByTestId('report-error');
    await expect(error).toBeAttached({ timeout: 30_000 });
    await expect(error).toContainText('שגיאה בהפקת דוח');
    const support = error.getByRole('link', { name: 'פנייה לתמיכה' });
    await expect(support).toHaveCount(1);

    const skip = page.getByTestId('skip-to-report');
    await expect(skip).toBeVisible();
    const s = await rect(page, 'skip-to-report');
    expect(s.scrollY).toBe(0);
    expect(s.bottom, 'ссылка «מעבר לדוח» не в первом экране 844').toBeLessThanOrEqual(NARROW.height);

    await skip.click();
    await expect.poll(() => reportColumnFocused(page), { message: 'фокус не на #report-column' }).toBe(true);
    await expect(error).toBeInViewport();
    await expect(support).toBeInViewport();

    await page.evaluate(() => window.scrollTo(0, 0));
    await skip.focus();
    await page.keyboard.press('Enter');
    await expect.poll(() => reportColumnFocused(page), { message: 'фокус не на #report-column после Enter' }).toBe(true);
    await expect(support).toBeInViewport();
  });

  test(`1440×900: «מעבר לדוח» скрыта, отчёт и ошибка на месте (раскладка не сломана) @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const id = await candidateIdByName(page, CANDIDATE);
    await page.goto(`/candidates/${id}/report`);
    await expect(page.getByTestId('report-summary')).toBeVisible({ timeout: 30_000 });
    // Источник: С1 брифа — на десктопе отчёт как был; ссылка нужна только на узкой ширине.
    await expect(page.getByTestId('skip-to-report')).toBeHidden();

    await forceGenerationError(page);
    await page.reload();
    await expect(page.getByTestId('report-error')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByTestId('report-error').getByRole('link', { name: 'פנייה לתמיכה' })).toBeVisible();
    await expect(page.getByTestId('skip-to-report')).toBeHidden();
  });
});
